-- NEXUS initial schema.
-- All identifiers are UUIDs generated by the API. JSONB columns hold validated
-- domain objects (run agents, plan, review) so snapshots remain stable even if
-- an agent configuration is edited later.

CREATE TABLE IF NOT EXISTS users (
  id uuid PRIMARY KEY,
  email text NOT NULL UNIQUE,
  name text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS projects (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name text NOT NULL,
  description text,
  color text NOT NULL DEFAULT '#A8C7FA',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS projects_user_updated_idx ON projects (user_id, updated_at DESC);

CREATE TABLE IF NOT EXISTS agents (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name text NOT NULL,
  role text NOT NULL CHECK (role IN ('planner', 'worker', 'reviewer', 'polisher', 'custom')),
  provider text NOT NULL CHECK (provider IN ('openai', 'anthropic', 'google')),
  model text NOT NULL,
  system_prompt text NOT NULL,
  temperature double precision NOT NULL DEFAULT 0.4,
  max_tokens integer NOT NULL DEFAULT 4096,
  accent text NOT NULL DEFAULT '#A8C7FA',
  is_default boolean NOT NULL DEFAULT false,
  enabled boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS agents_user_idx ON agents (user_id, created_at ASC);

CREATE TABLE IF NOT EXISTS templates (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name text NOT NULL,
  description text NOT NULL,
  category text NOT NULL,
  icon text NOT NULL DEFAULT 'sparkles',
  objective_template text NOT NULL,
  guidance text NOT NULL DEFAULT '',
  suggested_approval_mode text NOT NULL DEFAULT 'key'
    CHECK (suggested_approval_mode IN ('always', 'key', 'auto')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS templates_user_idx ON templates (user_id, created_at DESC);

CREATE TABLE IF NOT EXISTS runs (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  project_id uuid REFERENCES projects(id) ON DELETE SET NULL,
  title text NOT NULL,
  objective text NOT NULL,
  template_id text,
  status text NOT NULL DEFAULT 'queued'
    CHECK (status IN ('queued', 'running', 'paused', 'awaiting_approval', 'completed', 'failed', 'cancelled')),
  stage text NOT NULL DEFAULT 'plan'
    CHECK (stage IN ('plan', 'work', 'review', 'revise', 'polish', 'deliver')),
  approval_mode text NOT NULL DEFAULT 'key'
    CHECK (approval_mode IN ('always', 'key', 'auto')),
  agents jsonb NOT NULL DEFAULT '[]'::jsonb,
  plan jsonb,
  review jsonb,
  pending_approval jsonb,
  current_step integer NOT NULL DEFAULT 0,
  review_round integer NOT NULL DEFAULT 0,
  revision_count integer NOT NULL DEFAULT 0,
  error text,
  error_code text,
  total_tokens bigint NOT NULL DEFAULT 0,
  total_cost_usd numeric(14, 6) NOT NULL DEFAULT 0,
  final_artifact_id uuid,
  last_seq integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  started_at timestamptz,
  completed_at timestamptz
);
CREATE INDEX IF NOT EXISTS runs_user_created_idx ON runs (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS runs_user_status_idx ON runs (user_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS runs_project_idx ON runs (project_id, created_at DESC);

CREATE TABLE IF NOT EXISTS run_events (
  id bigserial PRIMARY KEY,
  run_id uuid NOT NULL REFERENCES runs(id) ON DELETE CASCADE,
  seq integer NOT NULL,
  type text NOT NULL,
  agent_id text,
  payload jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (run_id, seq)
);
CREATE INDEX IF NOT EXISTS run_events_run_seq_idx ON run_events (run_id, seq ASC);

CREATE TABLE IF NOT EXISTS artifacts (
  id uuid PRIMARY KEY,
  run_id uuid NOT NULL REFERENCES runs(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name text NOT NULL,
  kind text NOT NULL CHECK (kind IN ('document', 'code', 'deliverable')),
  mime_type text NOT NULL,
  content text NOT NULL,
  version integer NOT NULL DEFAULT 1,
  created_by_agent_id text,
  agent_name text,
  step_id text,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS artifacts_run_idx ON artifacts (run_id, created_at ASC);
CREATE INDEX IF NOT EXISTS artifacts_user_idx ON artifacts (user_id, created_at DESC);

CREATE TABLE IF NOT EXISTS usage_records (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  run_id uuid REFERENCES runs(id) ON DELETE SET NULL,
  agent_id text,
  agent_name text,
  provider text NOT NULL,
  model text NOT NULL,
  input_tokens integer NOT NULL DEFAULT 0,
  output_tokens integer NOT NULL DEFAULT 0,
  cost_usd numeric(14, 6) NOT NULL DEFAULT 0,
  latency_ms integer NOT NULL DEFAULT 0,
  status text NOT NULL DEFAULT 'success' CHECK (status IN ('success', 'error')),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS usage_user_created_idx ON usage_records (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS usage_run_idx ON usage_records (run_id);

CREATE TABLE IF NOT EXISTS credentials (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  provider text NOT NULL CHECK (provider IN ('openai', 'anthropic', 'google')),
  encrypted_key text NOT NULL,
  key_hint text NOT NULL,
  last_validated_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, provider)
);

CREATE TABLE IF NOT EXISTS run_instructions (
  id uuid PRIMARY KEY,
  run_id uuid NOT NULL REFERENCES runs(id) ON DELETE CASCADE,
  content text NOT NULL,
  stage text NOT NULL,
  consumed boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS run_instructions_run_idx ON run_instructions (run_id, created_at ASC);
